import sys
import os
import xml.etree.ElementTree as ET
from pathlib import Path
import time

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    items = []
    for item in root.findall('item'):
        key = item.get('key')
        value = item.get('value')
        items.append((key, value))
    return items

def load_cache(cache_path):
    try:
        with open(cache_path, 'r') as f:
            return [line.strip().split('=', 1) for line in f if line.strip()]
    except (IOError, OSError):
        return []

def save_cache(cache_path, items):
    with open(cache_path, 'w') as f:
        for key, value in items:
            f.write(f"{key}={value}\n")

def main():
    xml_path = sys.stdin.readline().strip()
    xml_path = Path(xml_path)
    cache_path = xml_path.parent / 'settings.cache'

    xml_mod_time = xml_path.stat().st_mtime
    cache_mod_time = cache_path.stat().st_mtime if cache_path.exists() else 0

    if cache_mod_time > xml_mod_time:
        items = load_cache(cache_path)
    else:
        items = parse_xml(xml_path)
        save_cache(cache_path, items)

    for key, value in items:
        print(f"{key}={value}")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
from pathlib import Path

def parse_xml_to_cache(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    cache_file = Path("settings.cache")
    cache_file.unlink(missing_ok=True)  # Clear existing cache file

    for item in root.findall('item'):
        key = item.get('key')
        value = item.get('value')
        if key and value:
            cache_file.write_text(f"{key}={value}\n", encoding='utf-8')

def read_cache_to_output():
    cache_file = Path("settings.cache")
    if cache_file.exists():
        with cache_file.open('r', encoding='utf-8') as f:
            for line in f:
                print(line.strip())

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python settings_cache.py <xml_file_path>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    parse_xml_to_cache(xml_path)
    read_cache_to_output()

import sys
import os

def process_config(input_path):
    cache_file = "settings.cache"
    with open(input_path, 'r') as config_file:
        lines = config_file.readlines()

    cache_data = {}
    for line in lines:
        line = line.strip()
        if not line or line.startswith('['):
            continue
        if '=' in line:
            section, key_value = line.split('=', 1)
            section = section.strip()
            key, value = key_value.split('=', 1)
            key = key.strip()
            value = value.strip()
            cache_data[f"{section}.{key}"] = value

    with open(cache_file, 'w') as cache:
        for key, value in cache_data.items():
            cache.write(f"{key}={value}\n")

def read_cache():
    cache_file = "settings.cache"
    if not os.path.exists(cache_file):
        return

    with open(cache_file, 'r') as cache:
        for line in cache:
            print(line.strip())

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python settings_cache.py <config_file_path>")
        sys.exit(1)

    input_path = sys.argv[1]
    process_config(input_path)
    read_cache()
